function c_out(int $status,array $data): void { http_response_code($status); echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function c_text($v,int $max=255): string { $s=trim((string)($v??'')); if(mb_strlen($s)>$max)c_out(422,['error'=>'Uno de los campos supera la longitud permitida.']); return $s; }
function c_schema(PDO $db): void {
  $adds=[['cliente','nombre',"ALTER TABLE cliente ADD COLUMN nombre VARCHAR(120) NOT NULL DEFAULT ''"],['cliente','apellidos',"ALTER TABLE cliente ADD COLUMN apellidos VARCHAR(160) NOT NULL DEFAULT ''"]];
  foreach($adds as [$t,$c,$sql]){ $q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?");$q->execute([$t,$c]);if(!(int)$q->fetchColumn())$db->exec($sql); }
  $db->exec("CREATE TABLE IF NOT EXISTS ubicacion (id_ubicacion INT AUTO_INCREMENT PRIMARY KEY, id_cliente INT NOT NULL, direccion_linea VARCHAR(255) NOT NULL, ciudad VARCHAR(255) NOT NULL, departamento VARCHAR(255) NOT NULL, codigo_postal VARCHAR(255) NULL, referencia VARCHAR(255) NULL, estado TINYINT NOT NULL DEFAULT 1, CONSTRAINT fk_ubicacion_cliente_cliente_api FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='ubicacion' AND column_name='estado'");$q->execute();if(!(int)$q->fetchColumn())$db->exec("ALTER TABLE ubicacion ADD COLUMN estado TINYINT NOT NULL DEFAULT 1");
  $db->exec("CREATE TABLE IF NOT EXISTS garantia_solicitud (id_garantia INT AUTO_INCREMENT PRIMARY KEY,id_venta INT NOT NULL,id_cliente INT NOT NULL,id_usuario_staff INT NOT NULL,id_producto INT NOT NULL,motivo VARCHAR(255) NOT NULL,diagnostico VARCHAR(255) NULL,estado VARCHAR(40) NOT NULL DEFAULT 'Solicitud recibida',fecha_solicitud DATE NOT NULL,fecha_cierre DATE NULL,INDEX idx_garantia_venta (id_venta),CONSTRAINT fk_garantia_venta_cliente_api FOREIGN KEY (id_venta) REFERENCES ventas(id_venta),CONSTRAINT fk_garantia_cliente_cliente_api FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente),CONSTRAINT fk_garantia_staff_cliente_api FOREIGN KEY (id_usuario_staff) REFERENCES staff(id_usuario_staff),CONSTRAINT fk_garantia_producto_cliente_api FOREIGN KEY (id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function c_user(PDO $db): array { if(empty($_SESSION['tm_cliente_id']))c_out(401,['error'=>'Inicia sesión con tu cuenta de cliente.']);$q=$db->prepare("SELECT c.id_cliente,c.id_usuario,c.nombre,c.apellidos,c.tipo_documento,c.numero_documento,c.correo,c.telefono,c.fecha_registro,c.estado,u.correo AS correo_usuario FROM cliente c INNER JOIN usuario u ON u.id_usuario=c.id_usuario WHERE c.id_cliente=? AND c.estado=1 AND u.estado=1 AND u.rol='Cliente' LIMIT 1");$q->execute([(int)$_SESSION['tm_cliente_id']]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u){unset($_SESSION['tm_cliente_id']);c_out(401,['error'=>'La cuenta no está activa. Inicia sesión nuevamente.']);}return $u; }
function c_google_config(): array {
  $file=__DIR__.'/config/google.php';
  if(!is_file($file)) return ['client_id'=>''];
  $cfg=require $file;
  return is_array($cfg)?$cfg:['client_id'=>''];
}
function c_google_schema(PDO $db): void {
  $db->exec("CREATE TABLE IF NOT EXISTS cliente_google (google_sub VARCHAR(255) NOT NULL PRIMARY KEY, id_cliente INT NOT NULL UNIQUE, fecha_vinculacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_cliente_google_cliente FOREIGN KEY (id_cliente) REFERENCES cliente(id_cliente) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function c_verify_google_token(string $token, string $clientId): array {
  if($token==='' || !preg_match('/^[0-9]+-[a-zA-Z0-9_-]+\.apps\.googleusercontent\.com$/',$clientId)) c_out(503,['error'=>'El ID de cliente OAuth de Google falta o no tiene un formato válido. Configura el ID real en config/google.php.']);
  if(strlen($token)>10000) c_out(422,['error'=>'Credencial de Google no válida.']);
  $url='https://oauth2.googleapis.com/tokeninfo?id_token='.rawurlencode($token);
  if(function_exists('curl_init')) {
    $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>10,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
  } else {
    $ctx=stream_context_create(['http'=>['timeout'=>10,'ignore_errors'=>true],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);$body=@file_get_contents($url,false,$ctx);$code=0;foreach(($http_response_header??[]) as $h){if(preg_match('/^HTTP\/\S+\s+(\d+)/',$h,$m))$code=(int)$m[1];}
  }
  $claims=is_string($body)?json_decode($body,true):null;
  if($code!==200 || !is_array($claims)) c_out(401,['error'=>'Google no pudo verificar la sesión. Inténtalo de nuevo.']);
  $issuer=(string)($claims['iss']??'');$email=filter_var((string)($claims['email']??''),FILTER_VALIDATE_EMAIL);$verified=filter_var((string)($claims['email_verified']??''),FILTER_VALIDATE_BOOLEAN);$exp=(int)($claims['exp']??0);
  if(!hash_equals($clientId,(string)($claims['aud']??'')) || !in_array($issuer,['accounts.google.com','https://accounts.google.com'],true) || !$email || !$verified || $exp<time() || empty($claims['sub'])) c_out(401,['error'=>'La identidad de Google no es válida o el correo no está verificado.']);
  return ['sub'=>(string)$claims['sub'],'email'=>strtolower((string)$email),'name'=>trim((string)($claims['name']??'')),'given_name'=>trim((string)($claims['given_name']??'')),'family_name'=>trim((string)($claims['family_name']??''))];
}
